package dev.engram.daily;
import java.io.*;
import java.nio.charset.StandardCharsets;
import java.util.*;
final class Gguf {
 private static final Set<String> SUPPORTED=new HashSet<>(Arrays.asList("llama","deci","falcon","grok","gpt2","gptj","gptneox","mpt","baichuan","starcoder","refact","bert","nomic-bert","jina-bert-v2","bloom","stablelm","qwen","qwen2","qwen2moe","qwen2vl","phi2","phi3","phimoe","plamo","codeshell","orion","internlm2","minicpm","minicpm3","gemma","gemma2","gemma3","starcoder2","mamba","xverse","command-r","cohere2","dbrx","olmo","olmo2","olmoe","openelm","arctic","deepseek","deepseek2","chatglm","bitnet","t5","t5encoder","jais","nemotron","exaone","rwkv6","rwkv6qwen2","rwkv7","arwkv7","granite","granitemoe","chameleon","wavtokenizer-dec","plm","bailingmoe"));
 private final RandomAccessFile f;
 private Gguf(File file)throws IOException{f=new RandomAccessFile(file,"r");}
 private byte[] read(int n)throws IOException{if(n<0||f.getFilePointer()+n>f.length()||f.getFilePointer()+n>32L*1024*1024)throw new IOException("Invalid, truncated or oversized GGUF metadata.");byte[] b=new byte[n];f.readFully(b);return b;}
 private long number(int n)throws IOException{byte[] b=read(n);long v=0;for(int i=0;i<n;i++)v|=(long)(b[i]&255)<<(8*i);if(v<0)throw new IOException("Invalid GGUF length.");return v;}
 private String string()throws IOException{long n=number(8);if(n>1024*1024)throw new IOException("GGUF string exceeds limit.");return new String(read((int)n),StandardCharsets.UTF_8);}
 private void skip(int type,int depth)throws IOException{int[] widths={1,1,2,2,4,4,4,1,0,0,8,8,8};if(type>=0&&type<widths.length&&widths[type]>0){read(widths[type]);return;}if(type==8){string();return;}if(type==9&&depth==0){int t=(int)number(4);long n=number(8);if(n>1000000)throw new IOException("GGUF array exceeds limit.");for(long i=0;i<n;i++)skip(t,1);return;}throw new IOException("Invalid GGUF metadata type.");}
 static void validate(File file)throws IOException{Gguf g=new Gguf(file);try{if(!new String(g.read(4),StandardCharsets.US_ASCII).equals("GGUF"))throw new IOException("Not a GGUF file.");long version=g.number(4);if(version!=2&&version!=3)throw new IOException("Unsupported GGUF version.");long tensors=g.number(8),count=g.number(8);if(tensors==0||count>100000)throw new IOException("Invalid GGUF header.");for(long i=0;i<count;i++){String key=g.string();int type=(int)g.number(4);if(key.equals("general.architecture")){if(type!=8)throw new IOException("Invalid architecture metadata.");String arch=g.string();if(arch.equals("clip")||arch.equals("mmproj"))throw new IOException("This is a multimedia projector (mmproj), not a chat model. Select the companion language-model GGUF.");if(!SUPPORTED.contains(arch))throw new IOException("Architecture "+arch+" is unsupported by bundled llama.cpp b5046. A runtime upgrade is required.");return;}g.skip(type,0);}throw new IOException("GGUF has no architecture metadata.");}finally{g.f.close();}}
}
